#include <sstream>
CamelPhatEditor::CamelPhatEditor(juce::AudioProcessor& p, juce::AudioProcessorValueTreeState& s): AudioProcessorEditor(p),state(s) {
    setSize(camelphat::kEditorWidth,camelphat::kEditorHeight);
    auto asset=[](juce::String n,int& size){ return BinaryData::getNamedResource(n.replaceCharacter('.','_').toRawUTF8(),size); };
    int size=0; const auto* data=asset("SkinParameters.txt",size);
    if (data) {
        juce::StringArray lines; lines.addLines(juce::String::fromUTF8(data,size));
        bool inControls=false;
        for(int i=0;i<lines.size();++i) {
            auto line=lines[i];
            if(line.trim()=="FontSelector" && i+3<lines.size()) { glyphs=lines[i+2]; std::istringstream widths(lines[i+3].toStdString()); int w; while(widths>>w)glyphWidths.push_back(w); }
            if(line.trim()=="FontDisplay" && i+3<lines.size() && lines[i+1].trim()=="75") { displayGlyphs=lines[i+2]; std::istringstream widths(lines[i+3].toStdString()); int w; while(widths>>w)displayWidths.push_back(w); }
            if(line.trim()=="FontVersion" && i+3<lines.size() && lines[i+1].trim()=="75") { versionGlyphs=lines[i+2]; std::istringstream widths(lines[i+3].toStdString()); int w; while(widths>>w)versionWidths.push_back(w); }
            if(line.trim()=="CONTROLS"){inControls=true;continue;}
            if(!inControls || line.trim().startsWith("---") || line.trim().isEmpty())continue;
            std::istringstream tokens(line.toStdString()); std::string name,type,image,page; Control c;
            if(!(tokens>>name>>type>>image>>page>>c.x>>c.y))continue;
            c.name=name;c.type=type;c.image=image;c.page=page; tokens>>c.x2>>c.y2;
            for(auto& spec:camelphat::kParameterSpecs)if(c.name==spec.name)c.id=spec.id;
            if(images.find(c.image)==images.end()){int bytes=0;auto* b=asset(c.image+".png",bytes); if(b) images[c.image]=juce::ImageFileFormat::loadFrom(b,static_cast<size_t>(bytes));}
            auto im=images[c.image];int w=im.getWidth(),h=im.getHeight();
            if(c.type=="Knob")h=w;
            else if(c.type=="OnButton"||c.type=="KickButton")h/=2;
            else if(c.type=="Selector"||c.type=="UpDownPreset")h/=3;
            if(c.x2>0)c.bounds={c.x,c.y,c.x2-c.x,c.y2-c.y};else c.bounds={c.x-w/2,c.y-h/2,(w/2)*2,(h/2)*2};
            if(c.type=="VSlider")c.bounds={c.x-w/2,c.y-h/2,c.x2-c.x+(w/2)*2,c.y2-c.y+(h/2)*2};
            controls.push_back(c);
        }
    }
    for(auto name:{"Background","LfoBkg","LfoSelect1","LfoSelect2","XYCursor","LevelMeterOff","FontSelector","FontVersion","FontDisplay"}){int bytes=0;auto* b=asset(juce::String(name)+".png",bytes);if(b)images[name]=juce::ImageFileFormat::loadFrom(b,static_cast<size_t>(bytes));}
    startTimerHz(30);
}
bool CamelPhatEditor::visible(const Control& c)const {return c.page=="Main"||c.page==(selectedLfo?"LfoPg2":"LfoPg1")||c.type=="RadioButton";}
juce::RangedAudioParameter* CamelPhatEditor::parameter(int id)const {return id>=0&&id<camelphat::kHostParameterCount?state.getParameter(camelphat::kParameterSpecs[static_cast<size_t>(id)].name):nullptr;}
float CamelPhatEditor::value(int id)const {if(auto* p=parameter(id))return p->getValue();return 0;}
void CamelPhatEditor::setValue(int id,float v){v=juce::jlimit(0.f,1.f,v);if(id==1||id==2){float low=value(1),high=value(2);if(value(6)>.5f){float delta=v-value(id);delta=std::max(-low,std::min(1.f-high,delta));v=value(id)+delta;if(auto* linked=parameter(id==1?2:1)){linked->beginChangeGesture();linked->setValueNotifyingHost(value(id==1?2:1)+delta);linked->endChangeGesture();}}else v=id==1?std::min(v,high):std::max(v,low);}if(auto* p=parameter(id)){p->setValueNotifyingHost(juce::jlimit(0.0f,1.0f,v));if(camelphat::kParameterSpecs[static_cast<size_t>(id)].smoothed){displayUntil=juce::Time::getMillisecondCounterHiRes()+3000.0;display=p->getText(p->getValue(),32);}repaint();}}
void CamelPhatEditor::drawText(juce::Graphics& g,const juce::String& text,int x,int y){auto im=images["FontSelector"];for(auto ch:text){int i=glyphs.indexOfChar(ch);if(i<0||i>=static_cast<int>(glyphWidths.size()))continue;int off=0;for(int j=0;j<i;++j)off+=glyphWidths[static_cast<size_t>(j)];int w=glyphWidths[static_cast<size_t>(i)];g.drawImage(im,x,y,w,im.getHeight(),off,0,w,im.getHeight());x+=w;}}
void CamelPhatEditor::paint(juce::Graphics& g){g.drawImageAt(images["Background"],0,0);g.drawImageAt(images["LfoBkg"],186,254);
 for(auto& c:controls){if(!visible(c))continue;juce::Graphics::ScopedSaveState controlClip(g);if(c.type!="RadioButton")g.reduceClipRegion(c.bounds);auto im=images[c.image];int w=im.getWidth(),h=im.getHeight();float v=value(c.id);
 if(c.type=="Knob"){int frame=juce::jlimit(0,h/w-1,int(v*static_cast<float>((h/w-1)*w))/w);g.drawImage(im,c.x-w/2,c.y-w/2,w,w,0,frame*w,w,w);}
 else if(c.type=="OnButton"||c.type=="KickButton"){h/=2;g.drawImage(im,c.x-w/2,c.y-h/2,w,h,0,(v>=0.5f||(c.type=="KickButton"&&pressedControl>=0&&controls[static_cast<size_t>(pressedControl)].name==c.name))?h:0,w,h);}
 else if(c.type=="Selector"||c.type=="UpDownPreset"){h/=3;g.drawImage(im,c.x-w/2,c.y-h/2,w,h,0,(pressedControl>=0&&controls[static_cast<size_t>(pressedControl)].name==c.name)?h*pressedFrame:0,w,h);if(auto* p=parameter(c.id)){int button=(c.id==44||c.id==45)?15:24;juce::Graphics::ScopedSaveState textClip(g);g.reduceClipRegion(c.bounds.reduced(button,0));drawText(g,p->getText(v,32),c.bounds.getX()+button+5,c.y-5);}}
 else if(c.type=="VSlider"){int y=c.y+int((1-v)*static_cast<float>(c.y2-c.y-h));g.drawImageAt(im,c.x-w/2,y-h/2);}
 else if(c.type=="MorphSquare"){g.drawImageAt(im,c.x-w/2,c.y-h/2);int sx=juce::jlimit(0,26,juce::roundToInt(value(44)*100.0f)),sy=juce::jlimit(0,26,juce::roundToInt(value(45)*100.0f));int cx=c.bounds.getX()+4+int(value(camelphat::kMorphTargets[static_cast<size_t>(sx)])*float(c.bounds.getWidth()-8));int cy=c.bounds.getY()+4+int((1.f-value(camelphat::kMorphTargets[static_cast<size_t>(sy)]))*float(c.bounds.getHeight()-8));g.setColour(juce::Colour(172,184,255).withAlpha(64.0f/255.0f));for(auto corner:{juce::Point<int>(c.bounds.getX()+1,c.bounds.getY()+1),juce::Point<int>(c.bounds.getRight(),c.bounds.getY()+1),juce::Point<int>(c.bounds.getX()+1,c.bounds.getBottom()),juce::Point<int>(c.bounds.getRight(),c.bounds.getBottom())})g.drawLine(float(cx),float(cy),float(corner.x),float(corner.y),1.f);g.setColour(juce::Colours::white);g.drawImageAt(images["XYCursor"],cx-4,cy-4);}
 else if(c.type=="RadioButton"){for(int k=0;k<2;++k){auto tab=images[k?"LfoSelect2":"LfoSelect1"];g.drawImage(tab,327+k*28,256,28,24,0,k==selectedLfo?24:0,28,24);}}
 else if(c.type=="VSliderBar"){int top=c.bounds.getY()+int((1.f-value(2))*float(c.bounds.getHeight()));int bottom=c.bounds.getBottom()-int(value(1)*float(c.bounds.getHeight()));if(bottom>top)g.drawImage(im,c.bounds.getX(),top,w,bottom-top,0,top-c.bounds.getY(),w,bottom-top);}
 else if(c.type=="VuMeter"){int mw=c.bounds.getWidth(),mh=c.bounds.getHeight();g.drawImage(images["LevelMeterOff"],c.x,c.y,mw,mh,0,0,mw,mh);if(metersEnabled){int ch=c.id==58?0:1;float level=juce::jlimit(0.f,1.f,meterValues[static_cast<size_t>(ch)]);int off=int((1.f-level)*31.f+.5f);int top=int(float(off)/31.f*float(h));top=std::min(top,mh);g.drawImage(im,c.x,c.y+top,mw,mh-top,0,top,mw,mh-top);}}
 else if(c.type=="TextDisplay"){juce::Graphics::ScopedSaveState clip(g);g.reduceClipRegion(c.bounds);drawDisplayText(g,display.isEmpty()?static_cast<CamelPhatProcessor&>(*getAudioProcessor()).presetSlotName(static_cast<CamelPhatProcessor&>(*getAudioProcessor()).currentPresetSlot()).fromLastOccurrenceOf(" / ",false,false):display,c.x,(c.y+c.y2)/2-images["FontDisplay"].getHeight()/2);}
 else if(c.type=="VersionDisplay")drawVersion(g);
 }
}
void CamelPhatEditor::selector(const Control& c){auto* p=parameter(c.id);if(!p)return;juce::PopupMenu menu;int n=c.id==14?33:(c.id==34||c.id==40?10:(c.id==44||c.id==45?27:23));for(int i=0;i<n;++i){float normalized=static_cast<float>(i)/100.0f;menu.addItem(i+1,p->getText(normalized,64),true,juce::approximatelyEqual(normalized,p->getValue()));}juce::Component::SafePointer<CamelPhatEditor> safe(this);menu.showMenuAsync(juce::PopupMenu::Options().withTargetScreenArea(localAreaToGlobal(c.bounds)),[safe,id=c.id](int result){if(safe&&result>0)if(auto* param=safe->parameter(id)){param->beginChangeGesture();safe->setValue(id,static_cast<float>(result-1)/100.0f);param->endChangeGesture();}});}
void CamelPhatEditor::mouseDown(const juce::MouseEvent& e){for(int i=static_cast<int>(controls.size())-1;i>=0;--i){auto& c=controls[static_cast<size_t>(i)];if(!visible(c)||!c.bounds.contains(e.getPosition()))continue;
 if(c.type=="RadioButton"){selectedLfo=e.x>=355?1:0;repaint();return;}
 if(c.type=="KickButton"){pressedControl=i;pressedFrame=1;static_cast<CamelPhatProcessor&>(*getAudioProcessor()).randomize();repaint();return;}
 if(c.type=="VuMeter"){metersEnabled=!metersEnabled;repaint();return;}
 if((e.mods.isPopupMenu()||e.mods.isCtrlDown())&&(c.type=="Knob"||c.type=="VSlider")){knobMenu(c);return;}
 if(c.type=="GlobalMenu"||c.type=="PresetMenu"){presetMenu(c);return;}
 if(c.type=="Selector"){int button=(c.id==44||c.id==45)?15:24;if(e.x<c.bounds.getX()+button||e.x>=c.bounds.getRight()-button){int max=c.id==14?32:(c.id==34||c.id==40?9:(c.id==44||c.id==45?26:22));pressedControl=i;pressedFrame=e.x<c.bounds.getX()+button?2:1;int selected=juce::roundToInt(value(c.id)*100.f)+(e.x<c.bounds.getX()+button?-1:1);if(auto* p=parameter(c.id)){p->beginChangeGesture();setValue(c.id,float(juce::jlimit(0,max,selected))/100.f);p->endChangeGesture();}}else selector(c);return;}
 if(c.type=="UpDownPreset"){auto* p=static_cast<CamelPhatProcessor*>(getAudioProcessor());int current=p->currentPresetSlot(),first=0,count=p->presetSlotCount();if(static_cast<CamelPhatProcessor&>(*p).isFactoryBank()&&current>=0&&current<int(camelphat::factoryPresets.size())){auto bank=juce::String(camelphat::factoryPresets[static_cast<size_t>(current)].bank);first=current;while(first>0&&bank==camelphat::factoryPresets[static_cast<size_t>(first-1)].bank)--first;int end=current+1;while(end<int(camelphat::factoryPresets.size())&&bank==camelphat::factoryPresets[static_cast<size_t>(end)].bank)++end;count=end-first;}if(count>0)p->selectPresetSlot(first+(current-first+(e.y<c.y?-1:1)+count)%count);return;}
 if(c.type=="MorphSquare"){if(e.mods.isPopupMenu()||e.mods.isCtrlDown()){juce::PopupMenu menu;menu.addItem(1,"Midi Learn X");menu.addItem(2,"Midi Learn Y");juce::Component::SafePointer<CamelPhatEditor> safe(this);menu.showMenuAsync(juce::PopupMenu::Options().withTargetScreenArea(localAreaToGlobal(c.bounds)),[safe](int result){if(safe&&(result==1||result==2)){int selected=juce::jlimit(0,26,juce::roundToInt(safe->value(result==1?44:45)*100.f));static_cast<CamelPhatProcessor&>(*safe->getAudioProcessor()).startMidiLearn(camelphat::kMorphTargets[static_cast<size_t>(selected)]);}});return;}dragging=i;for(int axis=0;axis<2;++axis){int selected=juce::jlimit(0,26,juce::roundToInt(value(axis?45:44)*100.f));if(auto* p=parameter(camelphat::kMorphTargets[static_cast<size_t>(selected)]))p->beginChangeGesture();}updateMorph(e.position);return;}
 if(auto* p=parameter(c.id)){p->beginChangeGesture();if(c.type=="OnButton"){setValue(c.id,value(c.id)>=0.5f?0:1);p->endChangeGesture();return;}dragging=i;dragStart=value(c.id);dragOrigin=e.position;return;}
 }}
void CamelPhatEditor::mouseDrag(const juce::MouseEvent& e){if(dragging<0)return;auto& c=controls[static_cast<size_t>(dragging)];if(c.type=="MorphSquare"){updateMorph(e.position);return;}float sensitivity=e.mods.isShiftDown()?1000.0f:200.0f;float v=dragStart+(dragOrigin.y-e.position.y)/sensitivity;if(c.type=="VSlider")v=dragStart+(dragOrigin.y-e.position.y)/(float(c.y2-c.y-images[c.image].getHeight())*(e.mods.isShiftDown()?10.f:1.f));else if(c.type=="Knob"&&circular){float angle=std::atan2(e.position.x-float(c.x),float(c.y)-e.position.y);v=(angle+juce::MathConstants<float>::pi*.75f)/(juce::MathConstants<float>::pi*1.5f);}setValue(c.id,v);}
void CamelPhatEditor::mouseUp(const juce::MouseEvent&){pressedControl=-1;pressedFrame=0;repaint();if(dragging>=0){if(controls[static_cast<size_t>(dragging)].type=="MorphSquare"){for(int axis=0;axis<2;++axis){int selected=juce::jlimit(0,26,juce::roundToInt(value(axis?45:44)*100.f));if(auto* p=parameter(camelphat::kMorphTargets[static_cast<size_t>(selected)]))p->endChangeGesture();}}else if(auto* p=parameter(controls[static_cast<size_t>(dragging)].id))p->endChangeGesture();}dragging=-1;}
void CamelPhatEditor::mouseWheelMove(const juce::MouseEvent& e,const juce::MouseWheelDetails& wheel){for(auto& c:controls)if(visible(c)&&c.bounds.contains(e.getPosition()))if(auto* p=parameter(c.id)){p->beginChangeGesture();setValue(c.id,value(c.id)+wheel.deltaY*0.1f);p->endChangeGesture();return;}}
void CamelPhatEditor::updateMorph(juce::Point<float> position){for(auto& c:controls)if(c.type=="MorphSquare"){for(int axis=0;axis<2;++axis){int selection=juce::roundToInt(value(axis?45:44)*100.0f);if(selection>=0&&selection<27){int target=camelphat::kMorphTargets[static_cast<size_t>(selection)];float v=axis?1.0f-(position.y-static_cast<float>(c.bounds.getY()+4))/static_cast<float>(c.bounds.getHeight()-8):(position.x-static_cast<float>(c.bounds.getX()+4))/static_cast<float>(c.bounds.getWidth()-8);setValue(target,v);}}return;}}

void CamelPhatEditor::timerCallback(){double now=juce::Time::getMillisecondCounterHiRes();if(now>displayUntil)display.clear();if(metersEnabled&&now-meterUpdated>60.0){auto& processor=static_cast<CamelPhatProcessor&>(*getAudioProcessor());std::array<float,2> next;for(int ch=0;ch<2;++ch)next[static_cast<size_t>(ch)]=float(std::pow(double(std::max(0.f,processor.meter(ch))),0.3676470518112183));if(std::fabs(next[0]-meterValues[0])>1.f/31.f||std::fabs(next[1]-meterValues[1])>1.f/31.f){meterValues=next;meterUpdated=now;}}repaint();}
void CamelPhatEditor::drawVersion(juce::Graphics& g){auto text=juce::String("v3.50.1.630");auto im=images["FontVersion"];int x=157-int(text.length())*6;for(auto ch:text){int index=versionGlyphs.indexOfChar(ch);if(index<0||index>=int(versionWidths.size()))continue;int offset=0;for(int i=0;i<index;++i)offset+=versionWidths[static_cast<size_t>(i)];int width=versionWidths[static_cast<size_t>(index)];g.drawImage(im,x,42,width,9,offset,0,width,9);x+=width;}}
void CamelPhatEditor::mouseDoubleClick(const juce::MouseEvent& e){for(auto& c:controls)if(visible(c)&&c.bounds.contains(e.getPosition())&&(c.type=="Knob"||c.type=="VSlider"))if(auto* p=parameter(c.id)){p->beginChangeGesture();setValue(c.id,camelphat::clearPreset[static_cast<size_t>(c.id)]);p->endChangeGesture();return;}}
void CamelPhatEditor::knobMenu(const Control& c){juce::PopupMenu menu;menu.addItem(1,"Midi Learn");if(c.type=="Knob"){menu.addItem(2,"Linear",true,!circular);menu.addItem(3,"Circular",true,circular);}juce::Component::SafePointer<CamelPhatEditor> safe(this);menu.showMenuAsync(juce::PopupMenu::Options().withTargetScreenArea(localAreaToGlobal(c.bounds)),[safe,id=c.id](int result){if(!safe)return;if(result==1){static_cast<CamelPhatProcessor&>(*safe->getAudioProcessor()).startMidiLearn(id);safe->display="Midi Learn";safe->displayUntil=juce::Time::getMillisecondCounterHiRes()+3000.0;}else if(result==2||result==3)safe->circular=result==3;});}
void CamelPhatEditor::presetMenu(const Control& c){juce::PopupMenu menu;menu.addItem(10001,"Load Preset...");menu.addItem(10004,"Load Bank...");menu.addItem(10002,"Save Preset...");menu.addItem(10005,"Save Bank...");menu.addItem(10003,"Clear Preset");menu.addSeparator();juce::String current;juce::PopupMenu bank;for(int i=0;i<int(camelphat::factoryPresets.size());++i){auto& preset=camelphat::factoryPresets[static_cast<size_t>(i)];if(current!=preset.bank){if(!current.isEmpty())menu.addSubMenu(current,bank);current=preset.bank;bank=juce::PopupMenu();}bank.addItem(i+1,static_cast<CamelPhatProcessor&>(*getAudioProcessor()).factoryPresetName(i),true,static_cast<CamelPhatProcessor&>(*getAudioProcessor()).isFactoryBank()&&i==static_cast<CamelPhatProcessor&>(*getAudioProcessor()).currentPresetSlot());}if(!current.isEmpty())menu.addSubMenu(current,bank);auto& processor=static_cast<CamelPhatProcessor&>(*getAudioProcessor());if(!processor.isFactoryBank()){juce::PopupMenu loaded;for(int i=0;i<processor.getNumPrograms();++i)loaded.addItem(20001+i,processor.getProgramName(i),true,i==processor.getCurrentProgram());menu.addSubMenu("Current Bank",loaded);}juce::Component::SafePointer<CamelPhatEditor> safe(this);menu.showMenuAsync(juce::PopupMenu::Options().withTargetScreenArea(localAreaToGlobal(c.bounds)),[safe](int result){if(!safe)return;if(result==10003)static_cast<CamelPhatProcessor&>(*safe->getAudioProcessor()).clearPreset();else if(result==10001||result==10002||result==10004||result==10005)safe->choosePresetFile(result==10001?0:(result==10002?1:(result==10004?-1:2)));else if(result>=20001){safe->getAudioProcessor()->setCurrentProgram(result-20001);safe->display.clear();safe->repaint();}else if(result>0&&result<=704){static_cast<CamelPhatProcessor&>(*safe->getAudioProcessor()).setFactoryProgram(result-1);safe->display.clear();safe->repaint();}});}
void CamelPhatEditor::choosePresetFile(int operation){bool save=operation>0;bool bank=operation==-1||operation==2;chooser=std::make_unique<juce::FileChooser>(save?(bank?"Save CamelPhat bank":"Save CamelPhat preset"):(bank?"Load CamelPhat bank":"Load CamelPhat preset"),juce::File(),bank?"*.fxb":(save?"*.fxp":"*.fxp;*.camelphat"));juce::Component::SafePointer<CamelPhatEditor> safe(this);int flags=juce::FileBrowserComponent::canSelectFiles|(save?juce::FileBrowserComponent::saveMode:juce::FileBrowserComponent::openMode);if(save)flags|=juce::FileBrowserComponent::warnAboutOverwriting;chooser->launchAsync(flags,[safe,save,bank](const juce::FileChooser& fc){if(!safe)return;auto file=fc.getResult();if(file==juce::File())return;auto& processor=static_cast<CamelPhatProcessor&>(*safe->getAudioProcessor());bool ok=true;if(save)ok=bank?processor.saveLegacyBank(file.withFileExtension("fxb")):processor.saveLegacyPreset(file.withFileExtension("fxp"));else if(file.hasFileExtension("fxb;fxp")){ok=processor.importLegacyBank(file);}else {juce::MemoryBlock state;ok=file.loadFileAsData(state);if(ok)processor.setStateInformation(state.getData(),int(state.getSize()));}if(!ok)juce::AlertWindow::showMessageBoxAsync(juce::MessageBoxIconType::WarningIcon,save?"Preset save failed":"Preset load failed","The selected file could not be "+juce::String(save?"saved.":"loaded."));safe->display.clear();safe->repaint();});}

void CamelPhatEditor::drawDisplayText(juce::Graphics& g,const juce::String& text,int x,int y){auto im=images["FontDisplay"];for(auto ch:text){int i=displayGlyphs.indexOfChar(ch);if(i<0||i>=int(displayWidths.size())){x+=6;continue;}int offset=0;for(int j=0;j<i;++j)offset+=displayWidths[static_cast<size_t>(j)];int w=displayWidths[static_cast<size_t>(i)];g.drawImage(im,x,y,w,im.getHeight(),offset,0,w,im.getHeight());x+=w;}}
